#!/usr/bin/env bun
/**
 * Iterative nemotron-nano-9b-v2 test with streaming observability.
 * Each question streams tokens, tool calls, and chain stages in real-time.
 * 5-minute wall clock timeout. Exits cleanly.
 */

import { HumanMessage, SystemMessage } from '@langchain/core/messages';
import { resetGraph } from '../agent/graph.js';
import { streamQuery } from '../agent/streaming.js';
import { closeDb, initDb } from '../db.js';
import { getModel } from '../openrouter.js';
import { buildSystemPrompt } from '../systemPrompt.js';

const TOTAL_TIMEOUT_MS = 5 * 60 * 1000;
const RUNS_PER_QUESTION = 3;
const TAB = '  ';

type FailureCategory =
  | 'sql_syntax'
  | 'sql_schema'
  | 'tool_loop'
  | 'hallucination'
  | 'wrong_answer'
  | 'refused'
  | 'no_clarification'
  | 'timeout'
  | 'crash';

interface Question {
  id: string;
  q: string;
  expected: string;
  tier: string;
}

const QUESTIONS: Question[] = [
  {
    id: 'simple-001',
    q: 'Who is the all-time NBA regular season scoring leader?',
    expected: 'LeBron James',
    tier: 'simple',
  },
  {
    id: 'simple-002',
    q: 'How many career points does LeBron James have?',
    expected: '43440',
    tier: 'simple',
  },
  {
    id: 'simple-003',
    q: 'Who won the NBA MVP award in the 2023-24 season?',
    expected: 'Nikola',
    tier: 'simple',
  },
  {
    id: 'multi-001',
    q: 'Who has more career points: Michael Jordan or Kobe Bryant?',
    expected: 'Kobe',
    tier: 'multi-step',
  },
  { id: 'vague-001', q: 'Who scored the most?', expected: 'CLARIFICATION', tier: 'vague' },
  {
    id: 'specific-001',
    q: 'What was Michael Jordan PER in the 1995 playoffs?',
    expected: 'NOT_AVAILABLE',
    tier: 'overly-specific',
  },
];

function categorize(
  run: { passed: boolean; answer: string; toolCalls: number },
  expected: string,
): FailureCategory {
  if (run.toolCalls >= 19) return 'tool_loop';
  if (expected === 'CLARIFICATION' && !run.passed) return 'no_clarification';
  if (expected === 'NOT_AVAILABLE' && !run.passed) return 'refused';
  if (!run.passed) {
    const a = run.answer.toLowerCase();
    if (/syntax error|parse error/.test(a)) return 'sql_syntax';
    if (/does not exist|no such/.test(a)) return 'sql_schema';
    return 'wrong_answer';
  }
  return 'wrong_answer';
}

async function streamQuestion(
  q: Question,
  run: number,
  prompt: string,
  deadline: number,
): Promise<{
  passed: boolean;
  answer: string;
  toolCalls: number;
  events: string[];
}> {
  const threadId = `nemotron-${q.id}-r${run}-${Date.now()}`;
  let answerText = '';
  let toolCalls = 0;
  const events: string[] = [];

  try {
    const gen = streamQuery([new SystemMessage(prompt), new HumanMessage(q.q)], threadId);

    for await (const event of gen) {
      if (Date.now() >= deadline) throw new Error('TIME_EXCEEDED');

      switch (event.type) {
        case 'chain_stage':
          events.push(`[${event.stage}]`);
          break;
        case 'token':
          process.stdout.write(event.content);
          answerText += event.content;
          break;
        case 'tool_start': {
          toolCalls++;
          const input = JSON.stringify(event.input).slice(0, 120);
          events.push(`\n${TAB}\u2192 tool: ${event.name}(${input})`);
          process.stdout.write(`\n${TAB}\u2192 \uD83D\uDD27 ${event.name}`);
          break;
        }
        case 'tool_end': {
          const out = event.output.slice(0, 100);
          events.push(`${TAB}  ${out}`);
          process.stdout.write(` \u2705\n${TAB}${out}`);
          break;
        }
        case 'tool_error':
          events.push(`${TAB}  \u274C ${event.error.slice(0, 80)}`);
          process.stdout.write(` \u274C\n${TAB}${event.error.slice(0, 80)}`);
          break;
        case 'usage':
          events.push(`${TAB}tokens: ${event.usage.inputTokens}\u2192${event.usage.outputTokens}`);
          break;
        case 'done':
          answerText =
            event.messages
              .map((m) => String(m.content || ''))
              .filter((c) => c.length > 0)
              .reverse()[0] || answerText;
          break;
        case 'error':
          throw new Error(event.message);
      }
    }
  } catch (e) {
    if (e instanceof Error && e.message === 'TIME_EXCEEDED') {
      events.push('[TIME_EXCEEDED]');
      process.stdout.write('\n[TIMEOUT]');
    } else {
      const msg = e instanceof Error ? e.message : String(e);
      events.push(`[ERROR: ${msg.slice(0, 80)}]`);
      process.stdout.write(`\n[${msg.slice(0, 60)}]`);
    }
    throw e;
  }

  const passed =
    q.expected === 'CLARIFICATION'
      ? /clarif|specify/i.test(answerText)
      : q.expected === 'NOT_AVAILABLE'
        ? /not available|do not have/i.test(answerText)
        : answerText.includes(q.expected);

  return { passed, answer: answerText.slice(0, 200), toolCalls, events };
}

async function main() {
  const startTime = Date.now();
  const deadline = startTime + TOTAL_TIMEOUT_MS;

  await initDb();
  const prompt = await buildSystemPrompt();

  const modelId = getModel();
  resetGraph();

  console.log(
    `\n\u2514\u2500 ${modelId} \u2014 ${RUNS_PER_QUESTION}runs \u00d7 ${QUESTIONS.length}questions`,
  );
  console.log(`\u251C\u2500 timeout: ${TOTAL_TIMEOUT_MS / 1000}s wall`);
  console.log(`\u2514${'\u2500'.repeat(50)}\n`);

  let totalPassed = 0;
  let totalAttempted = 0;

  for (const q of QUESTIONS) {
    if (Date.now() >= deadline) {
      console.log(`\u23F0 Wall timeout \u2014 stopping at ${q.id}`);
      break;
    }

    console.log(
      `\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 ${q.id} (${q.tier}): ${q.q} \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n`,
    );

    let qPassed = 0;
    let qRuns = 0;

    for (let run = 1; run <= RUNS_PER_QUESTION && Date.now() < deadline; run++) {
      qRuns++;
      process.stdout.write(`\n\u2500\u2500 run ${run}/${RUNS_PER_QUESTION} \u2500\u2500\n`);

      try {
        const result = await streamQuestion(q, run, prompt, deadline);
        totalAttempted++;
        if (result.passed) {
          totalPassed++;
          qPassed++;
        }

        const cat = categorize(result, q.expected);
        process.stdout.write(
          `\n${result.passed ? '\u2705 PASS' : `\u274C FAIL [${cat}]`} (tools:${result.toolCalls})\n`,
        );
      } catch {
        totalAttempted++;
        process.stdout.write('\n\u274C FAIL [timeout]\n');
      }
    }

    console.log(`\n\u2500\u2500 ${q.id} result: ${qPassed}/${qRuns} pass \u2500\u2500\n`);
  }

  const elapsed = Math.round((Date.now() - startTime) / 1000);
  console.log(`\n${'\u2550'.repeat(50)}`);
  console.log(`RESULT: ${totalPassed}/${totalAttempted} PASS in ${elapsed}s`);
  console.log(`${'\u2550'.repeat(50)}\n`);

  await closeDb();
}

main().catch((e) => {
  console.error('\nFATAL:', e);
  process.exit(1);
});

import { MessagesValue, StateSchema } from '@langchain/langgraph';
import { z } from 'zod/v4';

export type IntentCategory =
  | 'career_leaders'
  | 'season_leaders'
  | 'awards'
  | 'team_seasons'
  | 'games'
  | 'shot_charts'
  | 'play_by_play'
  | 'identity'
  | 'draft'
  | 'data_quality'
  | 'cross_schema'
  | 'general';

export const ChatbotState = new StateSchema({
  messages: MessagesValue,
  sqlRetryCount: z.number().optional(),
  intentCategory: z.string().optional(),
  totalToolCalls: z.number().optional(),
});

export type ChatbotStateType = (typeof ChatbotState)['State'];
export type ChatbotUpdateType = (typeof ChatbotState)['Update'];

