1	import type { BaseMessage } from '@langchain/core/messages';
2	import { SystemMessage, ToolMessage } from '@langchain/core/messages';
3	import { Command, END, MemorySaver, START, StateGraph } from '@langchain/langgraph';
4	import { ToolNode, toolsCondition } from '@langchain/langgraph/prebuilt';
5	import { ERROR_PREFIX } from '../utils/retry.js';
6	import { createModel } from './model.js';
7	import { buildIntentSchemaPrompt } from './schemaFilter.js';
8	import { ChatbotState, type ChatbotStateType } from './state.js';
9	import { nbaTools } from './tools.js';
10	
11	const MAX_SQL_RETRIES = 3;
12	const MAX_TOTAL_TOOL_CALLS = 10;
13	const LOOP_DETECTION_THRESHOLD = 3;
14	const HALLUCINATION_NUMBER_THRESHOLD = 500;
15	
16	const INTENT_PATTERNS: Array<{ pattern: RegExp; category: string }> = [
17	  {
18	    pattern:
19	      /\b(triple.doubles?|quadruple.doubles?|50.point|career\s+(points|rebounds|assists|steals|blocks|games|three|free\s+throw))\b/i,
20	    category: 'career_leaders',
21	  },
22	  {
23	    pattern:
24	      /\b(career\s+leader|all.time|most\s+(points|rebounds|assists|steals|blocks|three|games))\b/i,
25	    category: 'career_leaders',
26	  },
27	  {
28	    pattern:
29	      /\b(season\s+leader|points?\s+per\s+game|assists?\s+per\s+game|rebounds?\s+per\s+game|led\s+the\s+nba)\b/i,
30	    category: 'season_leaders',
31	  },
32	  {
33	    pattern:
34	      /\b(mvp|roy|rookie\s+of\s+the\s+year|dpoy|defensive\s+player|all.nba|all.defensive|all.star|all.rookie)\b/i,
35	    category: 'awards',
36	  },
37	  { pattern: /\b(award|honor|winner|vote)\b/i, category: 'awards' },
38	  {
39	    pattern:
40	      /\b(team\s+(record|season|rating|srs|pace|offensive|defensive)|warriors|bulls|celtics|lakers)\b/i,
41	    category: 'team_seasons',
42	  },
43	  {
44	    pattern: /\b(cross.check|cross\s+schema|between\s+(main|unified|bref|nbadb))\b/i,
45	    category: 'cross_schema',
46	  },
47	  {
48	    pattern: /\b(finals?\s+game|final\s+score|box\s+score|stat\s+line|game_id)\b/i,
49	    category: 'games',
50	  },
51	  {
52	    pattern:
53	      /\b(shot\s+chart|three\s+pointer|corner\s+three|mid.range|at\s+the\s+rim|shot\s+distribution)\b/i,
54	    category: 'shot_charts',
55	  },
56	  { pattern: /\b(play.by.play|turnover|made\s+shot)\b/i, category: 'play_by_play' },
57	  {
58	    pattern:
59	      /\b(basketball.reference\s+id|nba\s+api\s+(person_id|id)|identity\s+bridge|unresolved|ambiguous)\b/i,
60	    category: 'identity',
61	  },
62	  { pattern: /\b(draft\s+pick|draft|first\s+overall)\b/i, category: 'draft' },
63	  { pattern: /\b(data\s+quality|dq_results|row\s+count|audit)\b/i, category: 'data_quality' },
64	];
65	
66	function classifyQuestion(text: string): string {
67	  for (const { pattern, category } of INTENT_PATTERNS) {
68	    if (pattern.test(text)) return category;
69	  }
70	  return 'general';
71	}
72	
73	export { classifyQuestion };
74	
75	const SQL_ERROR_PREFIXES = [
76	  ERROR_PREFIX.SQL_ERROR,
77	  ERROR_PREFIX.SCHEMA_ERROR,
78	  ERROR_PREFIX.SYNTAX_ERROR,
79	  ERROR_PREFIX.TRANSIENT_ERROR,
80	  ERROR_PREFIX.SCHEMA_VALIDATION_FAILED,
81	];
82	
83	function containsSqlError(content: string): boolean {
84	  const firstLine = (content.split('\n')[0] ?? '').trim();
85	  return SQL_ERROR_PREFIXES.some((prefix) => firstLine.startsWith(prefix));
86	}
87	
88	function getTrailingToolMessages(state: ChatbotStateType): ToolMessage[] {
89	  const toolMessages: ToolMessage[] = [];
90	  for (let i = state.messages.length - 1; i >= 0; i--) {
91	    const message = state.messages[i];
92	    if (!ToolMessage.isInstance(message)) {
93	      break;
94	    }
95	    toolMessages.unshift(message);
96	  }
97	  return toolMessages;
98	}
99	
100	function trimMessagesForModel(state: ChatbotStateType) {
101	  const messages = state.messages;
102	  const systemMessages = messages.filter((message) => SystemMessage.isInstance(message));
103	  const nonSystemMessages = messages.filter((message) => !SystemMessage.isInstance(message));
104	  const retainedSystemMessages =
105	    systemMessages.length <= 5 ? systemMessages : [systemMessages[0]!, ...systemMessages.slice(-4)];
106	  return [...retainedSystemMessages, ...nonSystemMessages.slice(-40)];
107	}
108	
109	function getCheckpointer() {
110	  const persistDir = process.env['CHATBOT_PERSIST_DIR'];
111	  if (persistDir) {
112	    const { SqliteSaver } = require('@langchain/langgraph-checkpoint-sqlite') as {
113	      SqliteSaver: new (opts: { path: string }) => MemorySaver;
114	    };
115	    return new SqliteSaver({ path: persistDir });
116	  }
117	  return new MemorySaver();
118	}
119	
120	function buildGraph() {
121	  const model = createModel().bindTools([...nbaTools]);
122	
123	  async function callModel(state: ChatbotStateType): Promise<Partial<ChatbotStateType>> {
124	    const response = await model.invoke(trimMessagesForModel(state));
125	    return { messages: [response] };
126	  }
127	
128	  async function sqlCritic(state: ChatbotStateType): Promise<Partial<ChatbotStateType> | Command> {
129	    const toolMessages = getTrailingToolMessages(state);
130	    if (toolMessages.length === 0) {
131	      return new Command({ goto: 'llm', update: { sqlRetryCount: 0 } });
132	    }
133	
134	    const totalToolCalls = (state.totalToolCalls ?? 0) + toolMessages.length;
135	
