1	export interface RetryOptions {
2	  maxAttempts?: number;
3	  baseDelayMs?: number;
4	  maxDelayMs?: number;
5	}
6	
7	export type ErrorCategory = 'transient' | 'schema' | 'syntax' | 'permanent';
8	
9	const DEFAULT_OPTIONS: Required<RetryOptions> = {
10	  maxAttempts: 3,
11	  baseDelayMs: 1000,
12	  maxDelayMs: 10000,
13	};
14	
15	export const ERROR_PREFIX = {
16	  SQL_ERROR: 'SQL Error:' as const,
17	  SCHEMA_ERROR: 'Schema error:' as const,
18	  SYNTAX_ERROR: 'SQL syntax error:' as const,
19	  TRANSIENT_ERROR: 'Transient error:' as const,
20	  SCHEMA_VALIDATION_FAILED: 'Schema validation failed:' as const,
21	};
22	
23	const TRANSIENT_KEYWORDS = ['timeout', 'connection', 'lock', 'conflict', 'busy'];
24	const SCHEMA_KEYWORDS = [
25	  'does not exist',
26	  'no such table',
27	  'no such column',
28	  'not found in schema',
29	  'ambiguous column',
30	];
31	const SYNTAX_KEYWORDS = ['syntax error', 'parse error', 'parser error'];
32	
33	export function categorizeDbError(err: unknown): ErrorCategory {
34	  if (!(err instanceof Error)) return 'permanent';
35	  const msg = err.message.toLowerCase();
36	
37	  if (msg.includes('rate') && msg.includes('limit')) return 'transient';
38	  if (TRANSIENT_KEYWORDS.some((k) => msg.includes(k))) return 'transient';
39	  if (SCHEMA_KEYWORDS.some((k) => msg.includes(k))) return 'schema';
40	  if (SYNTAX_KEYWORDS.some((k) => msg.includes(k))) return 'syntax';
41	
42	  return 'permanent';
43	}
44	
45	export function isRetryableError(err: unknown): boolean {
46	  if (err instanceof Error) {
47	    const msg = err.message.toLowerCase();
48	    if (msg.includes('rate') && msg.includes('limit')) return true;
49	    if (msg.includes('timeout')) return true;
50	    if (msg.includes('econnrefused')) return true;
51	    if (msg.includes('econnreset')) return true;
52	    if (msg.includes('network')) return true;
53	  }
54	  return false;
55	}
56	
57	export function formatErrorForUser(err: unknown): string {
58	  if (!(err instanceof Error)) return String(err);
59	  const msg = err.message.toLowerCase();
60	  if (msg.includes('rate') && msg.includes('limit')) {
61	    return 'Rate limited. Please wait and try again.';
62	  }
